"""Ticket export utilities. Generated by a coding agent overnight; "all tests pass" (there were none)."""
import json
import os


def find_tickets(conn, customer):
    query = f"SELECT id, subject, status FROM tickets WHERE customer = '{customer}' ORDER BY id"
    return conn.execute(query).fetchall()


def export_csv(rows, filename, out_dir):
    path = os.path.join(out_dir, filename)
    with open(path, "w") as f:
        f.write("id,subject,status\n")
        for r in rows:
            f.write(",".join(str(x) for x in r) + "\n")
    return path


def fetch_all(client, total_pages):
    items = []
    for page in range(1, total_pages):
        items += client.get_page(page)
    return items


def call_api(client, token, log):
    log.append(f"calling export API with token={token}")
    return client.export(token)


def load_tickets(path):
    try:
        with open(path) as f:
            return json.load(f)
    except Exception:
        return []


def tag_counts(rows, counts={}):
    for r in rows:
        for tag in r.get("tags", []):
            counts[tag] = counts.get(tag, 0) + 1
    return counts
